import{_ as a,o as s,c as n}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse(`{"title":"Page 3 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"3","title":"Page 3 | Home","prev":"/page/2/","next":"/page/4/","posts":[{"title":"macOS下苹果手机刷机","url":"/posts/2023-11-11-flash-ios/","date":"2023-11-11 20:03","tags":["ios"],"html":"<p>苹果手机在大版本升级之后也会变得卡卡的，可以通过下载官方的固件包来刷机，这样可以让手机变得更流畅。</p>\\n<h2 id=\\"下载官方镜像\\" tabindex=\\"-1\\">下载官方镜像 <a class=\\"header-anchor\\" href=\\"#下载官方镜像\\" aria-label=\\"Permalink to &quot;下载官方镜像&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先我们需要下载官方的固件包，如果你有苹果开发者帐号，可以在<a href=\\"https://developer.apple.com/download/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Software Downloads</a>下载，如果没有帐号可以在 <a href=\\"https://ipsw.me/\\" target=\\"_blank\\" rel=\\"noreferrer\\">ipsw.me</a> 上找到对应的固件包。我的手机是 iPhone SE (2nd generation)，所以我下载的固件包名字是<code>iPhone12,8_17.1.1_21B91_Restore.ipsw</code>。</p>\\n<h2 id=\\"手机连接-mac-系统\\" tabindex=\\"-1\\">手机连接 Mac 系统 <a class=\\"header-anchor\\" href=\\"#手机连接-mac-系统\\" aria-label=\\"Permalink to &quot;手机连接 Mac 系统&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>MacOS 在版本 12 以上的系统中，已经不支持使用 iTunes 来管理手机了，所以我们需要使用 Finder 来管理手机。我们连接手机到 Mac 系统，这时候会弹出一个提示框，我们需要点击信任按钮。</p>\\n<h2 id=\\"开始刷机\\" tabindex=\\"-1\\">开始刷机 <a class=\\"header-anchor\\" href=\\"#开始刷机\\" aria-label=\\"Permalink to &quot;开始刷机&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>在 Finder 中可以看到我们连接的手机了，我们可以点击手机的名字，然后在右侧的窗口中点击 <code>Restore iPhone...</code> 按钮。需要注意的是，点击 Restore iPhone 按钮之前，需要按住 Option 键，这样才会弹出选择固件包的窗口。选择我们刚刚下载好的固件，就开始刷机了。刷机完成之后，系统会有弹窗提示，这时候我们断开手机和电脑的连接，手机就可以正常使用了。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>苹果的刷机比安卓简单很多，但是苹果的手机刷机是不能降级的，所以需要注意固件的版本。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://www.ithome.com/0/280/080.htm\\" target=\\"_blank\\" rel=\\"noreferrer\\">苹果 iPhone / iPad 刷机教程</a></p>\\n<p><a href=\\"https://betahub.cn/\\" target=\\"_blank\\" rel=\\"noreferrer\\">尝鲜派</a></p>\\n"},{"title":"macOS下编译C++文件","url":"/posts/2023-10-09-macos-build-cpp/","date":"2023-10-09 12:10","tags":["C++"],"html":"<p>WebAssembly 是一种新的编译目标，可以将 C/C++ 等语言编译成 WebAssembly，然后在浏览器中运行。我最近在研究如何把<a href=\\"https://github.com/mchehab/zbar\\" target=\\"_blank\\" rel=\\"noreferrer\\">zbar</a>编译成 WebAssembly，然后在浏览器中使用。第一步就是想把官方的例子编译成二进制测试下代码，但是在 MacOS 下编译的时候遇到了一些问题，这里记录下。</p>\\n<h2 id=\\"官方例子\\" tabindex=\\"-1\\">官方例子 <a class=\\"header-anchor\\" href=\\"#官方例子\\" aria-label=\\"Permalink to &quot;官方例子&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://github.com/mchehab/zbar/blob/master/examples/scan_image.cpp\\" target=\\"_blank\\" rel=\\"noreferrer\\">scan_image.cpp</a></p>\\n<p>官方提供了一个例子，可以用来测试二维码识别功能，这个例子有两个依赖 Magick++.h 和 zbar.h，这两个库都可以通过 brew 安装。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">brew</span><span style=\\"color:#032F62\\"> install</span><span style=\\"color:#032F62\\"> imagemagick</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">brew</span><span style=\\"color:#032F62\\"> install</span><span style=\\"color:#032F62\\"> zbar</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br></div></div><p>因为从源码编译对我来说实在是太复杂了，所以我就选择了直接安装相关依赖。</p>\\n<h2 id=\\"编译\\" tabindex=\\"-1\\">编译 <a class=\\"header-anchor\\" href=\\"#编译\\" aria-label=\\"Permalink to &quot;编译&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">g++</span><span style=\\"color:#005CC5\\"> -o</span><span style=\\"color:#032F62\\"> scan_image</span><span style=\\"color:#032F62\\"> scan_image.cpp</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>执行上面的命令，会报错：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>scan_image.cpp:1:10: fatal error: 'Magick++.h' file not found</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>这是因为 Magick++.h 的头文件在 <code>/opt/homebrew/include/ImageMagick-7/Magick++.h</code>，但是 g++ 默认只会在 <code>/opt/homebrew/include</code> 目录下查找头文件，所以我们需要指定头文件的路径。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">g++</span><span style=\\"color:#005CC5\\"> -o</span><span style=\\"color:#032F62\\"> scan_image</span><span style=\\"color:#032F62\\"> scan_image.cpp</span><span style=\\"color:#005CC5\\"> -I/opt/homebrew/include/ImageMagick-7</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>执行上面的命令还是会有报错：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>/opt/homebrew/include/ImageMagick-7/MagickCore/magick-config.h:63:3: warning: \\"you should set MAGICKCORE_QUANTUM_DEPTH to sensible default set it to configure time default\\" [-W#warnings]</span></span>\\n<span class=\\"line\\"><span># warning \\"you should set MAGICKCORE_QUANTUM_DEPTH to sensible default set it to configure time default\\"</span></span>\\n<span class=\\"line\\"><span>  ^</span></span>\\n<span class=\\"line\\"><span>/opt/homebrew/include/ImageMagick-7/MagickCore/magick-config.h:64:3: warning: \\"this is an obsolete behavior please fix your makefile\\" [-W#warnings]</span></span>\\n<span class=\\"line\\"><span># warning \\"this is an obsolete behavior please fix your makefile\\"</span></span>\\n<span class=\\"line\\"><span>  ^</span></span>\\n<span class=\\"line\\"><span>/opt/homebrew/include/ImageMagick-7/MagickCore/magick-config.h:86:3: error: \\"you should set MAGICKCORE_HDRI_ENABLE\\"</span></span>\\n<span class=\\"line\\"><span># error \\"you should set MAGICKCORE_HDRI_ENABLE\\"</span></span>\\n<span class=\\"line\\"><span>  ^</span></span>\\n<span class=\\"line\\"><span>/opt/homebrew/include/ImageMagick-7/MagickCore/magick-config.h:121:3: error: \\"you should set MAGICKCORE_HDRI_ENABLE\\"</span></span>\\n<span class=\\"line\\"><span># error \\"you should set MAGICKCORE_HDRI_ENABLE\\"</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br></div></div><p>我们需要设置两个 ImageMagick 需要的编译变量：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">g++</span><span style=\\"color:#005CC5\\"> -o</span><span style=\\"color:#032F62\\"> scan_image</span><span style=\\"color:#032F62\\"> scan_image.cpp</span><span style=\\"color:#005CC5\\"> -I/opt/homebrew/include/ImageMagick-7</span><span style=\\"color:#005CC5\\"> -DMAGICKCORE_QUANTUM_DEPTH=16</span><span style=\\"color:#005CC5\\"> -DMAGICKCORE_HDRI_ENABLE=0</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>设置了这两个变量之后，还是会报错：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>Undefined symbols for architecture arm64:</span></span>\\n<span class=\\"line\\"><span>  \\"Magick::Blob::Blob()\\", referenced from:</span></span>\\n<span class=\\"line\\"><span>      _main in scan_image-727bdc.o</span></span>\\n<span class=\\"line\\"><span>  \\"_zbar_get_symbol_name\\", referenced from:</span></span>\\n<span class=\\"line\\"><span>      zbar::Symbol::get_type_name() const in scan_image-727bdc.o</span></span>\\n<span class=\\"line\\"><span>ld: symbol(s) not found for architecture arm64</span></span>\\n<span class=\\"line\\"><span>clang: error: linker command failed with exit code 1 (use -v to see invocation)</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br></div></div><p>这是因为我们只引用了头文件，却没有引用相关库的实现。我们需要指定 ImageMagick 的库文件路径，这里我使用的是 brew 安装的 ImageMagick，所以库文件在 <code>/opt/homebrew/lib/ImageMagick</code> 目录下。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">g++</span><span style=\\"color:#005CC5\\"> -o</span><span style=\\"color:#032F62\\"> scan_image</span><span style=\\"color:#032F62\\"> scan_image.cpp</span><span style=\\"color:#005CC5\\"> -I/opt/homebrew/include/ImageMagick-7</span><span style=\\"color:#005CC5\\"> -L/opt/homebrew/lib/ImageMagick</span><span style=\\"color:#005CC5\\"> -DMAGICKCORE_QUANTUM_DEPTH=16</span><span style=\\"color:#005CC5\\"> -DMAGICKCORE_HDRI_ENABLE=0</span><span style=\\"color:#005CC5\\"> -lMagick++-7.Q16HDRI</span><span style=\\"color:#005CC5\\"> -lzbar</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>同时我们需要使用 -l 参数来指定需要链接的库，这里需要链接 Magick++-7.Q16HDRI 和 zbar。</p>\\n<h2 id=\\"cmake\\" tabindex=\\"-1\\">CMake <a class=\\"header-anchor\\" href=\\"#cmake\\" aria-label=\\"Permalink to &quot;CMake&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>上面的编译命令比较长，而且如果我们需要编译多个文件的时候，就需要写很多次，所以我们可以使用 CMake 来简化编译过程。</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>cmake_minimum_required(VERSION 3.10)</span></span>\\n<span class=\\"line\\"><span>project(ScanImage)</span></span>\\n<span class=\\"line\\"><span></span></span>\\n<span class=\\"line\\"><span></span></span>\\n<span class=\\"line\\"><span>set(CMAKE_CXX_STANDARD 11)</span></span>\\n<span class=\\"line\\"><span>set(CMAKE_CXX_FLAGS \\"-DMAGICKCORE_HDRI_ENABLE=1 -DMAGICKCORE_QUANTUM_DEPTH=16\\")</span></span>\\n<span class=\\"line\\"><span></span></span>\\n<span class=\\"line\\"><span>include_directories(/opt/homebrew/include/ImageMagick-7)</span></span>\\n<span class=\\"line\\"><span>link_directories(/opt/homebrew/lib/ImageMagick)</span></span>\\n<span class=\\"line\\"><span></span></span>\\n<span class=\\"line\\"><span>add_executable(ScanImage scan_image.cpp)</span></span>\\n<span class=\\"line\\"><span>target_link_libraries(ScanImage zbar Magick++-7.Q16HDRI)</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br></div></div><h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>C++ 的编译报错总是让人摸不着头脑，这里我只是简单的记录了下我遇到的问题和解决方案，希望能帮助到大家。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://stackoverflow.com/questions/17887265/how-to-include-third-party-libraries\\" target=\\"_blank\\" rel=\\"noreferrer\\">how to #include third party libraries</a></p>\\n<p><a href=\\"https://github.com/undecaf/zbar-wasm\\" target=\\"_blank\\" rel=\\"noreferrer\\">zbar-wasm</a></p>\\n"},{"title":"正则表达式匹配信用卡","url":"/posts/2023-07-09-credit-regex/","date":"2023-07-09 13:41","tags":["regex"],"html":"<p>最近在做支付相关的服务，需要检测用户输入的信用卡号是否合法，并且根据信用卡号规则显示对应的信用卡类型。这里记录一下如何使用正则表达式来匹配信用卡号。顺便说一下只有 AE 卡号的 CVV 是 4 位的，其他的都是 3 位。</p>\\n<h2 id=\\"银联卡\\" tabindex=\\"-1\\">银联卡 <a class=\\"header-anchor\\" href=\\"#银联卡\\" aria-label=\\"Permalink to &quot;银联卡&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>银联卡以 62 开头，借记卡是 19 位，信用卡是 14 位。一般支付的时候都是使用信用卡，所以我们只需要匹配 14 位的卡号。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> regex</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> RegExp</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'^62</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{14}'</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"visa\\" tabindex=\\"-1\\">Visa <a class=\\"header-anchor\\" href=\\"#visa\\" aria-label=\\"Permalink to &quot;Visa&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Visa 信用卡以 4 开头，新卡长度为 16 位，旧卡长度为 13 位。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> regex</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> RegExp</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'^4[0-9]{12}(?:[0-9]{3})?'</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"mastercard\\" tabindex=\\"-1\\">MasterCard <a class=\\"header-anchor\\" href=\\"#mastercard\\" aria-label=\\"Permalink to &quot;MasterCard&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>MasterCard 信用卡以 51 到 55 开头或者是以 2221–2720 开头，长度为 16 位。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> regex</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> RegExp</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'^(5[1-5]</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{0,2}|22[2-9]</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{1}|2[3-7]</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{2})</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{12}'</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"amex\\" tabindex=\\"-1\\">Amex <a class=\\"header-anchor\\" href=\\"#amex\\" aria-label=\\"Permalink to &quot;Amex&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Amex 信用卡以 34 或者 37 开头，长度为 15 位。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> regex</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> RegExp</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'^3[47]</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{13}'</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"jcb\\" tabindex=\\"-1\\">Jcb <a class=\\"header-anchor\\" href=\\"#jcb\\" aria-label=\\"Permalink to &quot;Jcb&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Jcb 信用卡以 35 开头，长度为 16 位。以 2131 或者 1800 开头，长度为 15 位。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> regex</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> RegExp</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'^(?:2131|1800|35</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{3})</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{11}'</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"diners\\" tabindex=\\"-1\\">Diners <a class=\\"header-anchor\\" href=\\"#diners\\" aria-label=\\"Permalink to &quot;Diners&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Diners 信用卡以 36、38 或者 30[0-5] 开头，长度为 14 位。</p>\\n<div class=\\"language-js line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">js</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> regex</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> RegExp</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'^3(?:0([0-5]|9)|[68]</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d)</span><span style=\\"color:#005CC5\\">\\\\\\\\</span><span style=\\"color:#032F62\\">d{11}'</span><span style=\\"color:#24292E\\">);</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>信用卡号的判断并不复杂，但是很多卡号有些特殊情况，需要注意。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://en.wikipedia.org/wiki/Payment_card_number\\" target=\\"_blank\\" rel=\\"noreferrer\\">Payment card number</a></p>\\n<p><a href=\\"https://www.regular-expressions.info/creditcard.html\\" target=\\"_blank\\" rel=\\"noreferrer\\">Finding or Verifying Credit Card Numbers</a></p>\\n"}]},"relativePath":"page/3/index.md","filePath":"page/[page].md"}`),e={name:"page/3/index.md"};function p(l,r,o,i,c,t){return s(),n("div")}const h=a(e,[["render",p]]);export{b as __pageData,h as default};
